import{_ as e,o as d,c as a,ak as o}from"./chunks/framework.DxrHb2fb.js";const u=JSON.parse('{"title":"服务与运行时","description":"","frontmatter":{},"headers":[],"relativePath":"runtime/index.md","filePath":"runtime/index.md","lastUpdated":1789465542000}'),r={name:"runtime/index.md"};function i(n,t,c,s,h,l){return d(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="服务与运行时" tabindex="-1">服务与运行时 <a class="header-anchor" href="#服务与运行时" aria-label="Permalink to &quot;服务与运行时&quot;">​</a></h1><p>组件册收录有解剖、有部件、可放置在页面上的组件。另有一类能力不是组件，却同样由本库对外提供：应用级配置、一次调用即弹出的对话框、把流式文本转换为节点的内核。它们没有 <code>data-part</code>，因此不进入组件册，本册收录这些能力。</p><table tabindex="0"><thead><tr><th>本册</th><th>内容</th><th>对应的包</th></tr></thead><tbody><tr><td><a href="./config">全局配置</a></td><td>应用级注入一次，语言与内建文案的默认值</td><td><code>@xihan-ui/vue</code></td></tr><tr><td><a href="./services">命令式服务</a></td><td><code>confirm()</code> / <code>toast.success()</code> 这类一次调用即出结果的入口</td><td><code>@xihan-ui/vue</code></td></tr><tr><td><a href="./markdown">流式 Markdown</a></td><td>传入截至当前的全文，返回一组带稳定 key 的已渲染块</td><td><code>@xihan-ui/markdown</code></td></tr><tr><td><a href="./code-highlight">代码着色</a></td><td>零依赖的粗粒度词法着色，也是一个可替换的端口</td><td><code>@xihan-ui/code-highlight</code></td></tr></tbody></table><h2 id="不在组件册中的原因" tabindex="-1">不在组件册中的原因 <a class="header-anchor" href="#不在组件册中的原因" aria-label="Permalink to &quot;不在组件册中的原因&quot;">​</a></h2><p>组件册每一页固定给出解剖、部件、状态机、connect API 与键盘规格，因为组件的契约即这几项。本册四项均不适用：全局配置是一个 provide 函数，命令式服务返回一个对象，Markdown 渲染器产出数据而不是 DOM。放入组件册只会使该册的页内结构失去意义。</p><p>但能力清单应当完整。按其他组件库的习惯查找对应能力时（Element Plus 的 <code>ElMessageBox</code>、Ant Design 的 <code>App.useApp()</code>、Naive UI 的 <code>useDialog</code>、Semi Design 的 Markdown 渲染器），它们在本册，不在组件册。</p>',6)])])}const _=e(r,[["render",i]]);export{u as __pageData,_ as default};
